        {phoneField(phone, setPhone)}
        {passwordField(t.password, t.passwordPlaceholder, password, setPassword, showPassword, () => setShowPassword(v => !v))}
        {passwordField(t.confirmPassword, t.confirmPlaceholder, confirmPassword, setConfirmPassword, showConfirm, () => setShowConfirm(v => !v))}
