      {otpError && <p className="mt-2 text-[13px] font-bold text-[var(--accent)]" role="alert">{otpError}</p>}
      {otpSuccess && <p className="mt-2 text-[13px] font-black text-[#18794E]">{otpSuccess}</p>}
