        <div className="flex items-start gap-2.5 p-3"><button onClick={() => setProfilePeer(authorKey)} aria-label={`${t.viewProfile} ${authorKey}`} className="flex h-11 w-11 shrink-0 items-center justify-center rounded-full bg-[var(--primary)] text-[16px] font-black text-white">{authorKey.slice(0, 1)}</button><div className="min-w-0 flex-1"><button onClick={() => setProfilePeer(authorKey)} className="flex flex-wrap items-center gap-1 text-start text-[14px] font-black [overflow-wrap:anywhere]">{authorKey}{p.verified && <BadgeCheck size={16} className="shrink-0 text-[var(--primary)]" />}{p.isUser && <span className="rounded-full bg-[#EAF6EE] px-2 py-0.5 text-[10px] font-black text-[#18794E]">{t.youBadge}</span>}</button><p className="mt-0.5 text-[11px] font-bold text-[var(--muted)] [overflow-wrap:anywhere]">{rtl ? p.timeAr : p.timeEn} • {rtl ? p.countryAr : p.countryEn} • {t.categories[p.cat]}</p></div><div className="flex shrink-0 flex-col gap-1.5"><button onClick={() => toggleFollow(authorKey)} className={`flex items-center justify-center gap-1 rounded-full px-3 py-1.5 text-[12px] font-black ${followedAuthors.has(authorKey) ? 'bg-[var(--soft)] text-[var(--primary)]' : 'bg-[var(--primary)] text-white'}`}>{followedAuthors.has(authorKey) ? <UserCheck size={14} /> : <UserPlus size={14} />}{followedAuthors.has(authorKey) ? t.followingBtn : t.followBtn}</button><button onClick={() => openDm(authorKey)} className="flex items-center justify-center gap-1 rounded-full bg-[var(--soft)] px-3 py-1.5 text-[12px] font-black text-[var(--primary)]"><MessageCircle size={14} />{t.messageBtn}</button></div></div>
