      <div className="mt-4 rounded-3xl border border-[var(--line)] bg-[var(--soft)] p-4"><p className="text-[14px] font-black">{t.photosTitle} — <span dir="ltr">0/12</span></p><p className="mt-2 text-[13px] font-bold leading-5 text-[var(--muted)] [overflow-wrap:anywhere]">{t.photosNote}</p><div className="mt-3 grid grid-cols-4 gap-2">{Array.from({ length: 4 }).map((_, i) => <div key={i} className="flex aspect-square items-center justify-center rounded-2xl border-2 border-dashed border-[#CBD2DF] bg-white text-[#98A2B3]"><Plus size={20} /></div>)}</div></div>
